  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), view('paid', 2, 1));
  assert.deepEqual(await h.ship('a'), { ok: true });
  assert.deepEqual(await h.order('a'), view('shipped', 2, 1));
  for (const m of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'create']) assert.equal((await h[m]('a')).ok, false);
  await h.__dispose();
});

test('failed charge, cancel draft, cancel paid refunds', async () => {
  const h = await createHost();
  await h.create('f'); await h.addItem('f'); await h.place('f');
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.deepEqual(await h.order('f'), view('declined', 1, 1));
  for (const m of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'create']) assert.equal((await h[m]('f')).ok, false);
  assert.deepEqual(await h.retryPayment('f'), { ok: true });
  assert.deepEqual(await h.order('f'), view('placed', 1, 2));
  assert.equal((await h.retryPayment('f')).ok, false);
  const second = await h.pendingEffects();
  assert.equal(second.length, 1);
  assert.deepEqual(second[0].data, { amount: 1 });
  await h.completeEffect(second[0].id, 'failed');
  assert.deepEqual(await h.order('f'), view('failed', 1, 2));
  assert.equal((await h.retryPayment('f')).ok, false);
  assert.equal((await h.cancel('f')).ok, false);

  await h.create('d');
  assert.deepEqual(await h.cancel('d'), { ok: true });
  assert.deepEqual(await h.order('d'), view('cancelled', 0));
  assert.equal((await h.cancel('d')).ok, false);

  await h.create('p'); await h.addItem('p'); await h.place('p');
  await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
  assert.deepEqual(await h.cancel('p'), { ok: true });
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'payment.refund');
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  await h.__dispose();
});

test('cancel while placed: ok refunds, failed does not', async () => {
  const h = await createHost();
  for (const o of ['k', 'n']) {
    await h.create(o); await h.addItem(o); await h.place(o);
    assert.deepEqual(await h.cancel(o), { ok: true });
    assert.deepEqual(await h.order(o), view('cancelling', 1, 1));
    for (const m of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment', 'create']) assert.equal((await h[m](o)).ok, false);
  }
  const effs = await h.pendingEffects();
  await h.completeEffect(effs.find((e) => e.from === 'k').id, 'ok');
  await h.completeEffect(effs.find((e) => e.from === 'n').id, 'failed');
  assert.deepEqual(await h.order('k'), view('cancelled', 1, 1, 1));
  assert.deepEqual(await h.order('n'), view('cancelled', 1, 1, 0));
  const left = await h.pendingEffects();
  assert.equal(left.length, 1);
  assert.equal(left[0].kind, 'payment.refund');
  assert.equal(left[0].from, 'k');

  // A retried charge can be cancelled too.
  await h.create('r'); await h.addItem('r'); await h.place('r');
  await h.completeEffect((await h.pendingEffects()).find((e) => e.from === 'r').id, 'failed');
  await h.retryPayment('r');
  assert.deepEqual(await h.cancel('r'), { ok: true });
  await h.completeEffect((await h.pendingEffects()).find((e) => e.from === 'r').id, 'failed');
  assert.deepEqual(await h.order('r'), view('cancelled', 1, 2, 0));
  await h.__dispose();
});

test('retry succeeds, then ship or cancel with refund', async () => {
  const h = await createHost();
  for (const o of ['s', 'c']) {
    await h.create(o); await h.addItem(o); await h.addItem(o); await h.addItem(o); await h.place(o);
    assert.equal((await h.retryPayment(o)).ok, false);
  }
  for (const e of await h.pendingEffects()) await h.completeEffect(e.id, 'failed');
  for (const o of ['s', 'c']) await h.retryPayment(o);
  for (const e of await h.pendingEffects()) await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.order('s'), view('paid', 3, 2));
  assert.deepEqual(await h.ship('s'), { ok: true });
  assert.deepEqual(await h.order('s'), view('shipped', 3, 2));
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.deepEqual(await h.order('c'), view('cancelled', 3, 2, 1));
  await h.__dispose();
});
